 p=Path(path);assert not p.exists();q=lambda s:"'"+str(s).replace("'","''")+"'";ps="$ErrorActionPreference='Stop';try{$r=Invoke-WebRequest -Uri "+q(url)+" -OutFile "+q(p)+" -PassThru -UseBasicParsing -TimeoutSec 40;@{HTTP=[int]$r.StatusCode;finalURL=$r.BaseResponse.ResponseUri.AbsoluteUri;contentType=[string]$r.Headers['Content-Type'];contentDisposition=[string]$r.Headers['Content-Disposition'];time=(Get-Date).ToUniversalTime().ToString('o');rateRemaining=[string]$r.Headers['X-RateLimit-Remaining']}|ConvertTo-Json -Compress}catch{$c=$null;if($_.Exception.Response){$c=[int]$_.Exception.Response.StatusCode};@{HTTP=$c;error=$_.Exception.Message;time=(Get-Date).ToUniversalTime().ToString('o')}|ConvertTo-Json -Compress}"
 cp=subprocess.run(['powershell','-NoProfile','-NonInteractive','-Command',ps],capture_output=True,text=True,encoding='utf-8',errors='replace')
